{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Spiramycin, the closest analogue (Morgan 0.3077), has an absolute oral bioavailability of 33% in healthy volunteers after a 1 g oral dose versus IV, directly supporting F >= 20% for this 16-membered macrolide class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Clarithromycin, a closely related macrolide, has an absolute oral bioavailability of 55% in humans, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Rosaramicin, a 16-membered macrolide, has an absolute bioavailability of 39% after oral tablet dosing, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Dirithromycin, a more distant macrolide prodrug, has only about 10% oral bioavailability, providing contradictory low-F evidence but with lower transferability to the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C02"],
      "claim": "EM574, an erythromycin-derived macrolide, has very low oral bioavailability (~2%) in humans, but its structural similarity to the query is low and it has distinct metabolic liabilities.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "Josamycin, a 16-membered macrolide, showed poor tablet bioavailability in humans, a contradictory data point, though its similarity to the query is low and the result is formulation-dependent.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high because the closest macrolide analogues (spiramycin, clarithromycin, rosaramicin) have absolute oral bioavailability values of 32-55%, all above the 20% threshold. Low-F analogues are structurally more distant or carry specific prodrug/metabolic liabilities, so the supportive evidence outweighs the physicochemical prior.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "Morgan similarity scores to the closest analogues are modest (<0.31), limiting quantitative transferability.",
    "Formulation-dependent absorption and first-pass metabolism for the exact structure are not directly characterized.",
    "The impact of the trimethoxy sugar and specific aglycone modifications on intestinal permeability and hepatic extraction is not experimentally defined."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

